@rendermode InteractiveServer

<span class="theme-indicator" style="color: @(Theme?.AccentColor ?? "#0078d4");">
    @GetThemeIcon() @(Theme?.Mode.ToString() ?? "System")
</span>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private string GetThemeIcon() => Theme?.Mode switch
    {
        ThemeMode.Light => "☀️",
        ThemeMode.Dark => "🌙",
        _ => "💻"
    };
}

@rendermode InteractiveServer
@inject CascadingValueSource<ThemeInfo> ThemeSource

<button class="btn btn-sm btn-outline-secondary" @onclick="CycleTheme"
        title="Toggle theme">
    @GetThemeIcon()
</button>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private string GetThemeIcon() => Theme?.Mode switch
    {
        ThemeMode.Light => "☀️",
        ThemeMode.Dark => "🌙",
        _ => "💻"
    };

    private async Task CycleTheme()
    {
        var current = Theme ?? new ThemeInfo();
        var next = new ThemeInfo
        {
            AccentColor = current.AccentColor,
            Mode = current.Mode switch
            {
                ThemeMode.Light => ThemeMode.Dark,
                ThemeMode.Dark => ThemeMode.System,
                _ => ThemeMode.Light
            }
        };
        await ThemeSource.NotifyChangedAsync(next);
    }
}

@page "/settings"
@rendermode InteractiveServer
@inject CascadingValueSource<ThemeInfo> ThemeSource

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card p-4" style="max-width: 480px;">
    <h4>Theme</h4>
    <div class="btn-group mb-3" role="group">
        @foreach (var t in Enum.GetValues<ThemeMode>())
        {
            <button class="btn @(t == currentMode ? "btn-primary" : "btn-outline-primary")"
                    @onclick="() => SetTheme(t)">
                @t
            </button>
        }
    </div>

    <h4>Accent Color</h4>
    <div class="d-flex align-items-center gap-2 mb-3">
        <input type="color" value="@currentAccent" @onchange="SetAccentColor" class="form-control form-control-color" />
        <span style="color: @currentAccent; font-weight: bold;">@currentAccent</span>
    </div>

    <div class="mt-3 p-3 border rounded" style="border-color: @currentAccent !important;">
        <strong>Preview:</strong> Theme = @currentMode, Accent = @currentAccent
    </div>
</div>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private ThemeMode currentMode;
    private string currentAccent = "#0078d4";

    protected override void OnParametersSet()
    {
        if (Theme is not null)
        {
            currentMode = Theme.Mode;
            currentAccent = Theme.AccentColor;
        }
    }

    private async Task SetTheme(ThemeMode mode)
    {
        currentMode = mode;
        await PushChanges();
    }

    private async Task SetAccentColor(ChangeEventArgs e)
    {
        currentAccent = e.Value?.ToString() ?? "#0078d4";
        await PushChanges();
    }

    private async Task PushChanges()
    {
        var updated = new ThemeInfo
        {
            Mode = currentMode,
            AccentColor = currentAccent
        };
        await ThemeSource.NotifyChangedAsync(updated);
    }
}

